#!/usr/bin/env node
/**
 * AI Sandbox HTTP wrapper for the Test 7 batch runner.
 *
 * Listens on port 3000 (ALB requirement) and satisfies the health check at
 * GET / while providing a simple API to trigger and monitor batch runs.
 *
 * Routes:
 *   GET  /        — HTML status page; always returns 200 (ALB health check)
 *   GET  /status  — JSON run state
 *   GET  /logs    — plain-text log tail  (?n=N lines, default 100)
 *   POST /run     — start a run; body is JSON with optional overrides:
 *                     { models, scenarios, defences, reps,
 *                       s3Bucket, s3Prefix, s3Region, awsRegion, runId }
 *                   Returns 202 if accepted, 409 if a run is already in progress.
 */

import http from "http";
import { spawn } from "child_process";
import { readFileSync, readdirSync, statSync } from "fs";
import path from "path";

const PORT = 3000;
const MAX_LOG_LINES = 20000;
const ENTRYPOINTS = {
  "1": "/docker-entrypoint-test1.sh",
  "3": "/docker-entrypoint-test3.sh",
  "3a": "/docker-entrypoint-test3a.sh",
  "4": "/docker-entrypoint-test4.sh",
  "7": "/docker-entrypoint.sh",
  "8": "/docker-entrypoint-test8.sh",
  "9": "/docker-entrypoint-test9.sh",
  "9a": "/docker-entrypoint-test9a.sh",
  "8b6": "/docker-entrypoint-test8b6.sh",
  "10": "/docker-entrypoint-test10.sh",
  "12": "/docker-entrypoint-test12.sh",
  "12a": "/docker-entrypoint-test12a.sh",
  "12b": "/docker-entrypoint-test12b.sh",
  "12c": "/docker-entrypoint-test12c.sh",
  "13": "/docker-entrypoint-test13.sh",
  "14": "/docker-entrypoint-test14.sh",
  "15": "/docker-entrypoint-test15.sh",
  "16": "/docker-entrypoint-test16.sh",
  "17": "/docker-entrypoint-test17.sh",
  "18": "/docker-entrypoint-test18.sh",
  "20": "/docker-entrypoint-test20.sh",
  "21": "/docker-entrypoint-test21.sh",
  "22": "/docker-entrypoint-test22.sh",
  "23": "/docker-entrypoint-test23.sh",
  "24": "/docker-entrypoint-test24.sh",
  "25": "/docker-entrypoint-test25.sh",
  "26": "/docker-entrypoint-test26.sh",
  "27": "/docker-entrypoint-test27.sh",
  "29": "/docker-entrypoint-test29.sh",
  "promptarmor-bedrock": "/docker-entrypoint-promptarmor-bedrock.sh",
  "injecagent": "/docker-entrypoint-injecagent.sh",
  "mt-agentrisk": "/docker-entrypoint-mt-agentrisk.sh",
  "test-framework": "/docker-entrypoint-test-framework.sh",
  "agentlab": "/docker-entrypoint-agentlab.sh",
  "mode4": "/docker-entrypoint-mode4.sh",
  "t3e": "/docker-entrypoint-t3e.sh",
  "t5": "/docker-entrypoint-t5.sh",
};
const DEFAULT_TEST = process.env.TEST_NUM || "7";
const BUILD_VERSION = JSON.parse(readFileSync(new URL("./package.json", import.meta.url), "utf8")).version;

// ---------------------------------------------------------------------------
// Run state
// ---------------------------------------------------------------------------

const INITIAL_PROGRESS = {
  totalCombinations: 0,
  completedCombinations: 0,
  failedCombinations: 0,
  completedRuns: 0,       // individual repetitions
  lastGES: null,
};

let state = {
  status: "idle",   // idle | running | done | failed
  runId: null,
  params: null,
  startedAt: null,
  finishedAt: null,
  exitCode: null,
  pid: null,
  logLines: [],
  progress: { ...INITIAL_PROGRESS },
};

let currentProcess = null;

function appendLog(line) {
  state.logLines.push(line);
  if (state.logLines.length > MAX_LOG_LINES) state.logLines.shift();
  process.stdout.write(line + "\n");

  // Track progress from log output
  // Total combinations: "[1/12]" pattern from entrypoint or ">>> N combinations queued"
  const totalMatch = line.match(/\[\d+\/(\d+)\]/);
  if (totalMatch) state.progress.totalCombinations = parseInt(totalMatch[1], 10);
  const queuedMatch = line.match(/>>> (\d+) combinations queued/);
  if (queuedMatch) state.progress.totalCombinations = parseInt(queuedMatch[1], 10);

  // Combination completed (Test 7: "Completed in", Test 3: "DONE in")
  if (/Completed in \d+s/.test(line) || /\] DONE in \d+s/.test(line)) {
    state.progress.completedCombinations++;
  }
  // Combination failed
  if (/WARNING: run failed/.test(line) || /\] FAILED:/.test(line)) {
    state.progress.completedCombinations++;
    state.progress.failedCombinations++;
  }

  // Individual test result (one per repetition)
  if (/^RESULT:/.test(line) || /^\s+RESULT:/.test(line)) {
    state.progress.completedRuns++;
  }
  // Extract GES from result blocks
  const gesMatch = line.match(/GES:\s+([\d.]+)/);
  if (gesMatch) state.progress.lastGES = parseFloat(gesMatch[1]);
}

function startRun(params) {
  const env = Object.assign({}, process.env);
  const testNum = String(params.test || DEFAULT_TEST);
  const entrypoint = ENTRYPOINTS[testNum];
  if (!entrypoint) {
    throw new Error(`Unknown test number: ${testNum}. Valid: ${Object.keys(ENTRYPOINTS).join(", ")}`);
  }

  // Test 7 env vars
  if (params.models)    env.TEST7_MODELS    = String(params.models);
  if (params.scenarios) env.TEST7_SCENARIOS = String(params.scenarios);
  if (params.defences)  env.TEST7_DEFENCES  = String(params.defences);
  if (params.reps)      env.TEST7_REPS      = String(params.reps);
  if (params.effort)    env.TEST7_EFFORT    = String(params.effort);
  if (params.runId)     env.TEST7_RUN_ID    = String(params.runId);

  // Test 3 env vars
  if (params.models)    env.TEST3_MODELS    = String(params.models);
  if (params.scenarios) env.TEST3_SCENARIOS = String(params.scenarios);
  if (params.defences)  env.TEST3_DEFENCES  = String(params.defences);
  if (params.parallel)  env.PARALLEL_JOBS   = String(params.parallel);
  if (params.runId)     env.TEST3_RUN_ID    = String(params.runId);

  // Test 1 env vars
  if (params.effort)    env.TEST1_EFFORT    = String(params.effort);
  if (params.config)    env.TEST1_CONFIG    = String(params.config);

  // Test 3a env vars
  if (params.efforts)   env.TEST3A_EFFORTS  = String(params.efforts);
  if (params.reps)      env.TEST3A_REPS     = String(params.reps);
  if (params.runId)     env.TEST3A_RUN_ID   = String(params.runId);

  // Test 9a env vars
  if (params.matrix)    env.TEST9A_MATRIX   = String(params.matrix);
  if (params.reps)      env.TEST9A_REPS     = String(params.reps);
  if (params.runId)     env.TEST9A_RUN_ID   = String(params.runId);

  // Test 8 env vars
  if (params.effort)    env.TEST8_EFFORT    = String(params.effort);
  if (params.reps)      env.TEST8_REPS      = String(params.reps);
  if (params.models)    env.TEST8_MODELS    = String(params.models);
  if (params.hardened)  env.TEST8_HARDENED   = "true";
  if (params.prompt)    env.TEST8_PROMPT     = String(params.prompt);
  if (params.b6)        env.TEST8_B6         = "true";

  // Test 8 B6 env vars
  if (params.effort)    env.TEST8B6_EFFORT  = String(params.effort);
  if (params.reps)      env.TEST8B6_REPS    = String(params.reps);
  if (params.models)    env.TEST8B6_MODELS  = String(params.models);

  // Test 10/11 env vars
  if (params.defences)      env.TEST10_DEFENCES     = String(params.defences);
  if (params.model)         env.TEST10_MODEL        = String(params.model);
  if (params.effort)        env.TEST10_EFFORT       = String(params.effort);
  if (params.judgeEffort)   env.TEST10_JUDGE_EFFORT = String(params.judgeEffort);
  if (params.reps)          env.TEST10_REPS         = String(params.reps);

  // Test 15 env vars (FPR under prompt v2)
  if (params.prompt)    env.TEST15_PROMPT   = String(params.prompt);
  if (params.task)      env.TEST15_TASK     = String(params.task);
  if (params.reps)      env.TEST15_REPS     = String(params.reps);
  if (params.model)     env.TEST15_MODEL    = String(params.model);

  // Test 25 env vars (AgentLAB)
  if (params.models)     env.TEST25_MODELS       = String(params.models);
  if (params.defences)   env.TEST25_DEFENCES     = String(params.defences);
  if (params.scenarios)  env.TEST25_SCENARIOS    = String(params.scenarios);
  if (params.attackTypes) env.TEST25_ATTACK_TYPES = String(params.attackTypes);
  if (params.seed)       env.TEST25_SEED         = String(params.seed);
  if (params.maxTurns)   env.TEST25_MAX_TURNS    = String(params.maxTurns);
  if (params.backend)    env.TEST25_BACKEND      = String(params.backend);
  if (params.runId)      env.TEST25_RUN_ID       = String(params.runId);

  // Mode 4 env vars (Paper14 §VII behavioural drift). Most callers will
  // pass these through `params.env`; these convenience mappings mirror the
  // entrypoint's env contract for the common knobs.
  if (params.models)     env.AGENT_MODELS = String(params.models);
  if (params.configs)    env.CONFIGS      = String(params.configs);
  if (params.floodTurns) env.FLOOD_TURNS  = String(params.floodTurns);
  if (params.reps)       env.REPETITIONS  = String(params.reps);
  if (params.rcThreshold) env.RC_THRESHOLD = String(params.rcThreshold);
  if (params.concurrency) env.RUNNER_CONCURRENCY = String(params.concurrency);
  if (params.runId)      env.RUN_ID       = String(params.runId);

  // Generic env passthrough (test 12 / AgentDojo uses this)
  if (params.env && typeof params.env === "object") {
    for (const [k, v] of Object.entries(params.env)) {
      env[k] = String(v);
    }
  }

  // Shared env vars
  if (params.s3Bucket)  env.S3_BUCKET       = String(params.s3Bucket);
  if (params.s3Prefix)  env.S3_PREFIX       = String(params.s3Prefix);
  if (params.s3Region)  env.S3_REGION       = String(params.s3Region);
  if (params.awsRegion) env.AWS_REGION      = String(params.awsRegion);
  if (params.bedrockRegion) env.BEDROCK_REGION = String(params.bedrockRegion);

  const runId = env.TEST7_RUN_ID || env.TEST3_RUN_ID || new Date().toISOString().replace(/[:.]/g, "");

  state = {
    status: "running",
    runId,
    params,
    startedAt: new Date().toISOString(),
    finishedAt: null,
    exitCode: null,
    pid: null,
    logLines: [],
    progress: { ...INITIAL_PROGRESS },
  };

  const child = spawn(entrypoint, [], {
    env,
    stdio: ["ignore", "pipe", "pipe"],
  });

  state.pid = child.pid;
  currentProcess = child;

  child

/**
 * Sensitive-env-var detection. Stand-alone module so both InMemorySessionStore
 * and DynamoSessionStore can call it without creating a circular import
 * with server-core.ts (which imports the stores).
 *
 * Two heuristics, OR-combined:
 *
 *  1. NAME suggests credential. Extended over the original
 *     KEY|SECRET|TOKEN|PASSWORD|CREDENTIAL|API regex to catch URL-style
 *     vars (DATABASE_URL, MONGO_URI, REDIS_URL, SMTP_URL, WEBHOOK_URL,
 *     CONNECTION_STRING, DSN…) that frequently embed user:password@host.
 *     Plus AUTH/PRIVATE/PASSWD/SMTP/WEBHOOK families.
 *
 *  2. VALUE looks like a credential regardless of name. Catches secrets
 *     that landed in unconventionally-named vars.
 *
 * False-positive cost is "we redact a non-secret value", which is annoying
 * for debugging but not a security regression. Worth it.
 */
export function isSensitiveEnvVar(name: string, value: string): boolean {
  // 1. Name-based check.
  if (/KEY|SECRET|TOKEN|PASSWORD|PASSWD|CREDENTIAL|API|AUTH|PRIVATE|DSN|URL|URI|CONNECTION|DATABASE|SMTP|WEBHOOK/i.test(name)) {
    return true;
  }
  // 2. Value-shape checks (only on strings of meaningful length).
  if (typeof value !== "string" || value.length < 8) return false;
  // URL with embedded user:password@host
  if (/^[a-z][a-z0-9+\-.]*:\/\/[^/\s]+:[^@\s]+@/i.test(value)) return true;
  // JWT shape (header.payload.signature where each segment is base64url)
  if (/^eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}/.test(value)) return true;
  // AWS access key family (AKIA, ASIA, etc. + 16 alnum chars)
  if (/^A(?:KIA|SIA|GPA|IDA|ROA|IPA|NPA|NVA)[0-9A-Z]{16}$/.test(value)) return true;
  // GitHub PAT (ghp_, gho_, ghu_, ghs_, ghr_)
  if (/^gh[pousr]_[A-Za-z0-9]{30,}$/.test(value)) return true;
  // Stripe keys
  if (/^sk_(?:live|test)_[A-Za-z0-9]{20,}$/.test(value)) return true;
  // Anthropic API keys
  if (/^sk-ant-[A-Za-z0-9_-]{20,}$/.test(value)) return true;
  return false;
}

/**
 * Clerk authentication for the dashboard container.
 *
 * Verifies Clerk session JWTs in the `Authorization: Bearer <token>` header
 * via `@clerk/backend`'s framework-neutral `verifyToken`. Used by every
 * `/api/*` route handler in `server-dashboard.ts` (except `/health` and
 * `/api/health`, which the platform's ALB and the dashboard's own browser
 * hits unauthenticated for status display).
 *
 * Two roles:
 *  - admin    — emails listed in ADMIN_EMAILS. Can change trust mode, see
 *               every user's API keys, sessions, and console logs.
 *  - user     — any other authenticated identity. Can only see their own
 *               sessions (via SessionStore.ownerSub), only their own API
 *               keys, and cannot toggle trust mode.
 *
 * The admin allow-list is hard-coded on purpose. There is no public
 * "promote to admin" endpoint and no env-var override — adding an admin
 * means a code change and a redeploy. That's the right shape for a
 * privilege you can't otherwise audit.
 *
 * Auth wiring:
 *   - publishable key (browser): CLERK_PUBLISHABLE_KEY OR
 *     NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY (whichever is set)
 *   - secret key (this module):  CLERK_SECRET_KEY
 *
 * If CLERK_SECRET_KEY is unset on a non-local deploy, every /api/* call
 * returns 503 "auth not configured" — fail-closed rather than expose
 * dashboard data.
 */

import { type IncomingMessage, type ServerResponse } from "node:http";
import { createPublicKey } from "node:crypto";
import { verifyToken } from "@clerk/backend";
import { json } from "./server-core.js";

const CLERK_SECRET_KEY = process.env.CLERK_SECRET_KEY ?? "";
export const CLERK_PUBLISHABLE_KEY =
  process.env.CLERK_PUBLISHABLE_KEY ??
  process.env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY ??
  "";

// Static JWKS public key. When set, verifyToken uses it directly and
// makes ZERO outbound network calls — sidesteps the egress allowlist
// problem entirely. The cost is that key rotation requires a redeploy
// (Clerk rotates ~yearly for instances, much rarer in practice).
//
// Two acceptable formats:
//   - PEM string: starts with "-----BEGIN PUBLIC KEY-----"
//   - JWK string: a single JSON object {"kty":"RSA","n":"…","e":"…",…}
// Either is fed to verifyToken({ jwtKey: <PEM> }) — verifyToken accepts
// PEM directly, and we convert JWK→PEM in code so operators can paste
// either shape into the env var.
//
// If unset, the SDK falls back to network JWKS discovery (the path that
// has been timing out from this Fargate task).
const CLERK_JWT_PUBLIC_KEY_RAW = process.env.CLERK_JWT_PUBLIC_KEY ?? "";

const CLERK_JWT_PUBLIC_KEY_PEM: string | null = (() => {
  const raw = CLERK_JWT_PUBLIC_KEY_RAW.trim();
  if (!raw) return null;
  if (raw.startsWith("-----BEGIN")) return raw;
  // Treat as JWK — try to parse and convert to PEM via Node's crypto.
  try {
    const jwk = JSON.parse(raw);
    const key = createPublicKey({ key: jwk, format: "jwk" });
    return key.export({ type: "spki", format: "pem" }) as string;
  } catch (err) {
    console.warn(
      `[clerk] CLERK_JWT_PUBLIC_KEY is set but not a valid PEM or JWK: ${
        err instanceof Error ? err.message : err
      }`,
    );
    return null;
  }
})();

/** Hard-coded admin allow-list. Changing this requires a code commit. */
const ADMIN_EMAILS = new Set<string>([
  "adrian.asher@checkout.com",
  "adrianasher30@gmail.com",
]);

export interface ClerkPrincipal {
  /** Clerk userId (sub claim) — stable across sessions; used as ownerSub
   *  when minting API keys. */
  userId: string;
  /** Primary verified email. Empty if Clerk didn't surface one. */
  email: string;
  /** Set true iff `email` is in ADMIN_EMAILS. */
  isAdmin: boolean;
  /** Raw verified claims. For audit / future scope checks. */
  claims: Record<string, unknown>;
}

export function isAdminEmail(email: string | null | undefined): boolean {
  if (!email) return false;
  return ADMIN_EMAILS.has(email.toLowerCase());
}

function extractBearer(req: IncomingMessage): string | null {
  const h = req.headers.authorization;
  if (typeof h !== "string") return null;
  const m = /^\s*Bearer\s+(\S+)\s*$/i.exec(h);
  return m ? m[1] : null;
}

function extractEmail(claims: Record<string, unknown>): string {
  // Clerk session JWTs contain a "primary_email_address_id" + a custom
  // template can include "email". We accept either; preferring "email"
  // because that's what we ask Clerk to put in the template.
  const direct = claims["email"];
  if (typeof direct === "string") return direct.toLowerCase();
  const eml = claims["primary_email"];
  if (typeof eml === "string") return eml.toLowerCase();
  // Fall back to userId so admin checks always fail gracefully when the
  // template is misconfigured (no admin promotion ever via a missing claim).
  return "";
}

/**
 * Verify the Clerk token on `req` without writing to `res`. Used by
 * /api/whoami where we want to surface "no auth yet" rather than 401.
 * Returns the principal on success, or a structured failure reason on
 * failure — the dashboard surfaces the reason in the sign-in overlay
 * so a misconfigured Clerk origin doesn't look like a generic "401".
 */
export type ClerkVerifyResult =
  | { ok: true; principal: ClerkPrincipal }
  | { ok: false; reason: "no-secret" | "no-token" | "no-sub" | "verify-failed"; error?: string };

export async function tryVerifyClerk(req: IncomingMessage): Promise<ClerkVerifyResult> {
  if (!CLERK_SECRET_KEY) return { ok: false, reason: "no-secret" };
  const token = extractBearer(req);
  if (!token) return { ok: false, reason: "no-token" };
  try {
    // Prefer the static public key when it's been provisioned — that
    // path is offline and never goes near the egress allowlist. Falls
    // back to the network JWKS discovery flow when the env var is unset.
    const verifyOpts: any = CLERK_JWT_PUBLIC_KEY_PEM
      ? { jwtKey: CLERK_JWT_PUBLIC_KEY_PEM }
      : { secretKey: CLERK_SECRET_KEY };
    const claims = await verifyToken(token, verifyOpts);
    const userId = (claims as any).sub;
    if (typeof userId !== "string" || !userId) {
      return { ok: false, reason: "no-sub" };
    }
    const email = extractEmail(claims as Record<string, unknown>);
    return {
      ok: true,
      principal: {
        userId,
        email,
        isAdmin: isAdminEmail(email),
        claims: claims as Record<string, unknown>,
      },
    };
  } catch (err) {
    // Surface the real cause. undici's "fetch failed" hides the actual
    // network error in err.cause (e.g. ENOTFOUND, ECONNREFUSED, TLS
    // failures, 4xx from a proxy). Without unwrapping it, an operator
    // sees "fetch failed" and can't tell DNS from egress firewall.
    const top = err instanceof Error ? err.message : String(err);
    const cause = (err as any)?.cause;
    const causeMsg =
      cause instanceof Error
        ? `${cause.name}: ${cause.message}` +
          ((cause as any).code ? ` (code=${(cause as any).code})` : "")
        : cause
          ? String(cause)
          : "";
    const error = causeMsg ? `${top} — cause: ${causeMsg}` : top;
    console.warn(`[clerk] verifyToken failed: ${error}`);
    return { ok: false, reason: "verify-failed", error };
  }
}

/**
 * Explicit egress probe. The dashboard's settings modal pings this so
 * an operator can tell whether Clerk's APIs are reachable from the
 * container without fishing through CloudWatch logs.
 *
 * Returns one entry per host the runtime actually contacts:
 *  - frontend-api: <slug>.clerk.accounts.dev — derived from the
 *    publishable key, used by the browser SDK + by some discovery
 *    paths in @clerk/backend.
 *  - backend-api: api.clerk.com — used by @clerk/backend.verifyToken
 *    to fetch the JWKS for signature verification. THIS is the host
 *    the firewall most often forgets.
 *
 * The result is an array so a partial allowlist (one host reachable,
 * one not) is visible at a glance.
 */
export async function probeClerkConnectivity(): Promise<{
  hosts: Array<{
    label: string;
    host: string;
    url: string;
    ok: boolean;
    status?: number;
    error?: string;
  }>;
}> {
  const hosts: Array<{
    label: string;
    host: string;
    url: string;
    ok: boolean;
    status?: number;
    error?: string;
  }> = [];

  // 1. Frontend API — derived from publishable key.
  const partsB64 = CLERK_PUBLISHABLE_KEY ? CLERK_PUBLISHABLE_KEY.split("_")[2] ?? "" : "";
  let frontendHost = "";
  if (partsB64) {
    try {
      frontendHost = Buffer.from(partsB64, "base64").toString("utf8").replace(/\$$/, "");
    } catch {
      /* leave empty */
    }
  }
  if (frontendHost) {
    hosts.push(
      await probeOne(
        "frontend-api",
        frontendHost,
        `https://${frontendHost}/.well-known/jwks.json`,
      ),
    );
  } else {
    hosts.push({
      label: "frontend-api",
      host: "(unknown)",
      url: "",
      ok: false,
      error: "Could not derive frontend-api host (publishable key missing or malformed)",
    });
  }

  // 2. Backend API — what @clerk/backend.verifyToken actually fetches
  // when it needs the JWKS. Always api.clerk.com regardless of dev/prod
  // for keys minted from the standard Clerk hosting plane.
  hosts.push(await probeOne("backend-api", "api.clerk.com", "https://api.clerk.com/v1/jwks"));

  return { hosts };
}

async function probeOne(
  label: string,
  host: string,
  url: string,
): Promise<{
  label: string;
  host: string;
  url: string;
  ok: boolean;
  status?: number;
  error?: string;
}> {
  try {
    const r = await fetch(url, { method: "GET", signal: AbortSignal.timeout(5_000) });
    return { label, host, url, ok: r.ok, status: r.status };
  } catch (err) {
    const top = err instanceof Error ? err.message : String(err);
    const cause = (err as any)?.cause;
    const causeMsg =
      cause instanceof Error
        ? `${cause.name}: ${cause.message}` +
